from fractions import Fraction
import itertools

def check_product(b_list, target):
    """Calculates the product and checks if it matches the target."""
    if not b_list:
        return False
    product = 1
    for b in b_list:
        product *= Fraction(b - 1, b)
    return product == target

def check_structural_constraints(b_list):
    """Checks for required factors 5, 67, and 7 in b_j or b_j - 1."""
    has_5 = any(b % 5 == 0 for b in b_list)
    has_67 = any(b % 67 == 0 for b in b_list)
    # Requirement: at least one b_j - 1 is divisible by 7
    has_7_numerator = any((b - 1) % 7 == 0 for b in b_list)
    return has_5 and has_67 and has_7_numerator

target = Fraction(14, 335)
B_MAX = 150
B_MIN = 3

# --- M = 2 Search ---
print("--- M = 2 Search ---")
solutions_m2 = []
# Iterate over distinct pairs (b1, b2) where b1 < b2
for b1 in range(B_MIN, B_MAX):
    for b2 in range(b1 + 1, B_MAX):
        b_list = [b1, b2]
        if check_structural_constraints(b_list):
            if check_product(b_list, target):
                solutions_m2.append(b_list)
                print(f"Found solution for M=2: {b_list}")

if not solutions_m2:
    print("No solutions found for M=2 within bounds.")

# --- M = 3 Search ---
print("\n--- M = 3 Search ---")
solutions_m3 = []
# Iterate over distinct triplets (b1, b2, b3) where b1 < b2 < b3
for b1 in range(B_MIN, B_MAX):
    for b2 in range(b1 + 1, B_MAX):
        for b3 in range(b2 + 1, B_MAX):
            b_list = [b1, b2, b3]
            if check_structural_constraints(b_list):
                if check_product(b_list, target):
                    solutions_m3.append(b_list)
                    print(f"Found solution for M=3: {b_list}")

if not solutions_m3:
    print("No solutions found for M=3 within bounds.")

